commands.command:
/usr/bin/bash -lc "jq -n --slurpfile findings /workspace/.exp_agent/findings_round_01.json --slurpfile report /workspace/.exp_agent/round_completion_01.json '
  def k: \"\\(.relative_path)|\\(.rule)|\\(.line)|\\(.column)\";
  ("'$findings[0] | map(k) | sort) as $f |
  ($report[0].entity_repairs | map(. as $e | .locations[] | {relative_path:$e.relative_path, rule:$e.rule} + . | k) | sort) as $r |
  {frozen_locations:($f|length), reported_locations:($r|length), missing:([$f[] | select(($r|index(.))|not)]), extra:([$r[] | select(($f|index(.))|not)]), exact:($f == $r)}
'"'"

/usr/bin/bash -lc "python3 - <<'PY'
import json
f=json.load(open('.exp_agent/findings_round_02.json'))
r=json.load(open('.exp_agent/round_completion_02.json'))
covered=[]
for e in r['entity_repairs']:
  for l in e['locations']:
    covered.append((e['relative_path'],e['rule'],l['line'],l['column']))
missing=[]
for x in f:
  if (x['relative_path'],x['rule'],x['line'],x['column']) not in covered: missing.append(x)
print('frozen',len(f),'reported',len(covered),'missing',len(missing))
for x in missing: print(x)
print('rules',sorted(set(x['rule'] for x in f)))
PY"
